// Generated by scripts/sync-core.mjs from Nexora-Saas src/lib/workforce/project-pages.ts. Do not edit: change the web repository and run npm run sync:core.
import type { ProjectPage } from "../../types/work-projects"

/*
 * Project pages (P5): a small wiki and meeting notes per project. Checklist
 * lines ("- [ ] …") are action items; each can become a task, and the line
 * then carries the task's key so it links to it.
 */

const CHECK = /^(\s*[-*]\s+\[)( |x|X)(\]\s+)(.*)$/
const KEY = /\b[A-Z][A-Z0-9]*(?:-[A-Z0-9]+)*#\d+\b/

export interface ActionItem {
  /** Index of the line in the body */
  line: number
  text: string
  done: boolean
  /** The task key when the line already became a task */
  key?: string
}

/** The action items of a page, in order. */
export function actionItems(body: string): ActionItem[] {
  return body
    .replace(/\r\n?/g, "\n")
    .split("\n")
    .flatMap((raw, line) => {
      const m = raw.match(CHECK)
      if (!m) return []
      const text = m[4]!.trim()
      if (!text) return []
      const key = text.match(KEY)?.[0]
      return [{ line, text, done: m[2] !== " ", ...(key ? { key } : {}) }]
    })
}

/** The title a task made from an action item gets: no key, no @mentions of the person picked, no extra spaces. */
export function actionTitle(text: string, mentionedName?: string): string {
  let out = text.replace(KEY, "").replace(/\s*→\s*$/, "")
  if (mentionedName) out = out.replace(new RegExp(`@${mentionedName.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}`, "i"), "")
  return out.replace(/\s{2,}/g, " ").replace(/^[\s,:;—-]+|[\s,:;—-]+$/g, "").slice(0, 200)
}

/** The body with the task's key added to an action item's line. */
export function linkActionToTask(body: string, line: number, key: string): string {
  const lines = body.replace(/\r\n?/g, "\n").split("\n")
  const m = lines[line]?.match(CHECK)
  if (!m || KEY.test(m[4]!)) return body
  lines[line] = `${m[1]}${m[2]}${m[3]}${m[4]!.trimEnd()} → ${key}`
  return lines.join("\n")
}

/** Pinned first, then meeting notes newest first, then pages by title. */
export function sortPages(pages: ProjectPage[]): ProjectPage[] {
  const rank = (p: ProjectPage) => (p.pinned ? 0 : p.kind === "meeting" ? 1 : 2)
  return [...pages].sort(
    (a, b) =>
      rank(a) - rank(b) ||
      (a.kind === "meeting" && b.kind === "meeting" ? (b.meetingDate ?? "").localeCompare(a.meetingDate ?? "") : 0) ||
      a.title.localeCompare(b.title)
  )
}

/** What a new page of each kind starts with. */
export function pageTemplate(kind: ProjectPage["kind"], labels: { agenda: string; notes: string; actions: string }): string {
  return kind === "meeting" ? `## ${labels.agenda}\n- \n\n## ${labels.notes}\n\n\n## ${labels.actions}\n- [ ] ` : ""
}

export const MAX_PAGE_LENGTH = 20_000
